videoplayer={init:function(){$.getScript({url:"/dvl/assets/js/video.min.js",success:function(){var i,t=$(".video-player");t.each(function(t,s){$(this).addClass("video-js"),i=videojs(this,{controls:!0,autoplay:!1},function(){var i=this.id(),t=this.textTracks(),s=$("#"+i).find(".vjs-captions-button");s.on("click",function(i){i.preventDefault();for(var s=0;s<t.length;s++){var a=t[s];$(this).hasClass("activate")?(a.mode="hidden",$(this).removeClass("activate")):"captions"===a.kind&&($(this).addClass("activate"),a.mode="showing")}})})})}})}},$(".video-player").length&&videoplayer.init();